/**
 * Flag + dial-code country selector with local number input.
 * Outputs full E.164 format: "+254712345678"
 */
import { ChevronDown, CircleAlert } from 'lucide-react'
import type { ChangeEvent } from 'react'
import { useEffect, useId, useMemo, useRef, useState } from 'react'

import { cx } from '~/lib/cx'
import type { PhoneCountry } from '~/lib/phone-countries'
import {
  flagUrl,
  parsePhoneNumber,
  PHONE_COUNTRIES,
} from '~/lib/phone-countries'

import { Label } from './label'
import styles from './phone-input.module.scss'

const DEFAULT_ISO2 = 'KE'

function defaultCountry(): PhoneCountry {
  return PHONE_COUNTRIES.find((c) => c.iso2 === DEFAULT_ISO2)!
}

export interface PhoneInputProps {
  label?: string
  hint?: string
  error?: string
  required?: boolean
  /** Full E.164 value, e.g. "+254712345678" or "" */
  value?: string | null
  onChange?: (full: string) => void
  onBlur?: () => void
  disabled?: boolean
  wrapClass?: string
}

export function PhoneInput({
  label,
  hint,
  error,
  required,
  value,
  onChange,
  onBlur,
  disabled,
  wrapClass,
}: PhoneInputProps) {
  const external = value ?? ''
  const initialParsed = parsePhoneNumber(external)

  const [state, setState] = useState(() => ({
    external,
    country: initialParsed?.country ?? defaultCountry(),
    local: initialParsed?.local ?? '',
  }))
  const [open, setOpen] = useState(false)
  const [search, setSearch] = useState('')

  const wrapRef = useRef<HTMLDivElement>(null)
  const searchRef = useRef<HTMLInputElement>(null)
  const id = useId()
  const listboxId = `${id}-listbox`

  // Derive the controls from the latest external value during render, so a
  // form reset updates the UI without a setState-in-effect round trip.
  let country = state.country
  let local = state.local
  if (state.external !== external) {
    const parsed = parsePhoneNumber(external)
    country = parsed?.country ?? defaultCountry()
    local = parsed?.local ?? ''
  }
  const setCountry = (next: PhoneCountry) => setState({ external, country: next, local })
  const setLocal = (next: string) => setState({ external, country, local: next })

  const filteredCountries = useMemo(() => {
    const q = search.toLowerCase().trim()
    if (!q) return PHONE_COUNTRIES
    return PHONE_COUNTRIES.filter(
      (c) =>
        c.name.toLowerCase().includes(q) ||
        c.dialCode.includes(q) ||
        c.iso2.toLowerCase().includes(q),
    )
  }, [search])

  function emit(c: PhoneCountry, l: string) {
    const digits = l.replace(/\D/g, '')
    const full = digits ? `+${c.dialCode}${digits}` : ''
    onChange?.(full)
  }

  function handleLocalInput(event: ChangeEvent<HTMLInputElement>) {
    const digits = event.currentTarget.value.replace(/[^0-9]/g, '')
    setLocal(digits)
    emit(country, digits)
  }

  function selectCountry(c: PhoneCountry) {
    setCountry(c)
    setOpen(false)
    setSearch('')
    emit(c, local)
  }

  useEffect(() => {
    function onDocClick(event: MouseEvent) {
      if (!wrapRef.current?.contains(event.target as Node)) setOpen(false)
    }
    document.addEventListener('click', onDocClick, true)
    return () => document.removeEventListener('click', onDocClick, true)
  }, [])

  useEffect(() => {
    if (!open) return
    queueMicrotask(() => searchRef.current?.focus({ preventScroll: true }))
  }, [open])

  const hasError = Boolean(error)

  return (
    <div className={cx(styles.root, wrapClass)} ref={wrapRef}>
      {label ? (
        <Label htmlFor={id} required={required} hint={hint} hintId={`${id}-hint`}>
          {label}
        </Label>
      ) : null}

      <div className={styles.field}>
        <div
          className={cx(
            styles.row,
            hasError && styles.invalid,
            disabled && styles.disabled,
          )}
        >
          <button
            type="button"
            className={styles.countryButton}
            onClick={() => setOpen((v) => !v)}
            aria-label={`Country code: ${country.name} +${country.dialCode}. Change country`}
            aria-haspopup="listbox"
            aria-expanded={open}
            aria-controls={open ? listboxId : undefined}
          >
            <img
              src={flagUrl(country.iso2)}
              alt=""
              width={24}
              height={18}
              className={styles.flag}
              loading="lazy"
            />
            <span className={styles.dialCode}>+{country.dialCode}</span>
            <ChevronDown
              aria-hidden
              className={cx(styles.chevron, open && styles.chevronOpen)}
            />
          </button>

          <input
            id={id}
            type="tel"
            inputMode="numeric"
            autoComplete="tel-national"
            placeholder={country.placeholder}
            disabled={disabled}
            value={local}
            aria-invalid={hasError || undefined}
            aria-describedby={
              hasError ? `${id}-error` : hint ? `${id}-hint` : undefined
            }
            onChange={handleLocalInput}
            onBlur={onBlur}
            className={styles.input}
          />

          {hasError ? (
            <span className={styles.errorIcon}>
              <CircleAlert size={16} aria-hidden />
            </span>
          ) : null}
        </div>

        {open ? (
          <div
            id={listboxId}
            role="listbox"
            aria-label="Countries"
            onKeyDown={(event) => {
              if (event.key === 'Escape') {
                event.stopPropagation()
                setOpen(false)
              }
            }}
            className={styles.dropdown}
          >
            <div className={styles.searchWrap}>
              <input
                ref={searchRef}
                type="text"
                placeholder="Search country or code…"
                aria-label="Search countries"
                autoComplete="off"
                value={search}
                onChange={(event) => setSearch(event.currentTarget.value)}
                className={styles.searchInput}
              />
            </div>

            <div className={styles.list}>
              {filteredCountries.length > 0 ? (
                filteredCountries.map((c) => (
                  <button
                    key={c.iso2}
                    type="button"
                    role="option"
                    aria-selected={country.iso2 === c.iso2}
                    className={cx(
                      styles.option,
                      country.iso2 === c.iso2 && styles.optionSelected,
                    )}
                    onClick={() => selectCountry(c)}
                  >
                    <img
                      src={flagUrl(c.iso2)}
                      alt=""
                      width={24}
                      height={18}
                      className={styles.flag}
                      loading="lazy"
                    />
                    <span className={styles.optionName}>{c.name}</span>
                    <span className={styles.optionCode}>+{c.dialCode}</span>
                  </button>
                ))
              ) : (
                <p className={styles.empty}>No countries found</p>
              )}
            </div>
          </div>
        ) : null}
      </div>

      {error ? (
        <p id={`${id}-error`} role="alert" className={cx(styles.message, styles.errorText)}>
          {error}
        </p>
      ) : null}
    </div>
  )
}

@use 'styles' as vz;

.root {
  display: flex;
  flex-direction: column;
  gap: vz.space(1);
  min-width: 0;
}

.field {
  position: relative;
  min-width: 0;
}

.row {
  display: flex;
  align-items: center;
  border: 1px solid vz.color('border');
  border-radius: vz.radius('lg');
  background: vz.color('card');
  color: vz.color('foreground');
  transition:
    border-color vz.duration('base') vz.ease('out'),
    box-shadow vz.duration('base') vz.ease('out');

  &:focus-within {
    border-color: vz.color('ring');
    box-shadow: 0 0 0 2px vz.color('ring', 0.25);
  }
}

.invalid {
  border-color: vz.color('destructive');

  &:focus-within {
    border-color: vz.color('destructive');
    box-shadow: 0 0 0 2px vz.color('destructive', 0.25);
  }
}

.disabled {
  opacity: 0.6;
  pointer-events: none;
}

.country-button {
  display: flex;
  flex: none;
  align-items: center;
  gap: vz.space(1.5);
  padding-block: vz.space(2.5);
  padding-inline: vz.space(3) vz.space(2);
  border: 0;
  border-inline-end: 1px solid vz.color('border');
  border-start-start-radius: vz.radius('lg');
  border-end-start-radius: vz.radius('lg');
  background: transparent;
  color: vz.color('foreground');
  font-family: inherit;
  font-size: vz.font-size('sm');
  cursor: pointer;
  user-select: none;
  transition: background-color vz.duration('fast') vz.ease('out');

  @include vz.hover {
    background: vz.color('muted');
  }

  @include vz.focus-ring(2px, -2px, 0.6);
}

.flag {
  flex: none;
  width: 24px;
  height: 18px;
  border-radius: 2px;
  object-fit: cover;
}

.dial-code {
  color: vz.color('muted-foreground');
  font-weight: 500;
}

.chevron {
  flex: none;
  color: vz.color('muted-foreground');
  transition: transform vz.duration('fast') vz.ease('out');

  @include vz.motion-reduce {
    transition: none;
  }
}

.chevron-open {
  transform: rotate(180deg);
}

.input {
  flex: 1;
  min-width: 0;
  padding-block: vz.space(2.5);
  padding-inline: vz.space(3);
  border: 0;
  background: transparent;
  color: vz.color('foreground');
  font-family: inherit;
  font-size: vz.font-size('sm');
  caret-color: vz.color('primary');
  outline: none;

  @include vz.placeholder {
    color: vz.color('muted-foreground');
  }
}

.error-icon {
  display: flex;
  flex: none;
  align-items: center;
  padding-inline-end: vz.space(3);
  color: vz.color('destructive');
}

.dropdown {
  position: absolute;
  inset-block-start: calc(100% + #{vz.space(1)});
  inset-inline-start: 0;
  z-index: vz.z('popover');
  display: flex;
  flex-direction: column;
  width: 18rem;
  max-width: 100%;
  max-height: 18rem;
  overflow: hidden;
  border: 1px solid vz.color('border');
  border-radius: vz.radius('xl');
  background: vz.color('card');
  color: vz.color('card-foreground');
  box-shadow: vz.elevation(2);
}

.search-wrap {
  flex: none;
  padding: vz.space(2);
  border-bottom: 1px solid vz.color('border');
}

.search-input {
  width: 100%;
  min-width: 0;
  padding: vz.space(2) vz.space(3);
  border: 1px solid vz.color('border');
  border-radius: vz.radius('lg');
  background: vz.color('card');
  color: vz.color('foreground');
  font-family: inherit;
  font-size: vz.font-size('sm');
  outline: none;

  @include vz.placeholder {
    color: vz.color('muted-foreground');
  }

  &:focus-visible {
    border-color: vz.color('ring');
    box-shadow: 0 0 0 2px vz.color('ring', 0.25);
  }
}

.list {
  flex: 1;
  overflow-y: auto;

  @include vz.scrollbar(8px);
}

.option {
  display: flex;
  align-items: center;
  gap: vz.space(2.5);
  width: 100%;
  padding: vz.space(2) vz.space(3);
  border: 0;
  background: transparent;
  color: vz.color('foreground');
  font-family: inherit;
  font-size: vz.font-size('sm');
  text-align: left;
  cursor: pointer;
  transition: background-color vz.duration('fast') vz.ease('out');

  @include vz.hover {
    background: vz.color('accent');
  }

  &:focus-visible {
    background: vz.color('accent');
    outline: none;
  }
}

.option-selected {
  background: vz.color('muted');
  font-weight: 500;
}

.option-name {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.option-code {
  flex: none;
  color: vz.color('muted-foreground');
  font-size: vz.font-size('xs');
}

.empty {
  margin: 0;
  padding: vz.space(4) vz.space(3);
  color: vz.color('muted-foreground');
  font-size: vz.font-size('xs');
  text-align: center;
}

.message {
  margin: 0;
  font-size: vz.font-size('xs');
}

.error-text {
  color: vz.color('destructive');
}
